/* SPDX-License-Identifier: GPL-3.0-only */
/* Owner contract LX-REQ-006/022, replayed through production input queues,
 * sequencer clock and SMC feedback. No device or physical-light claim. */
#define SMC_UI_MAIN smc_ui_baseline_main
#include "smc_ui_test.c"

static void pause_edge(int host, int down)
{
    if (host) {
        CHECK(smc_midi_host((down ? 9u : 8u) | (down ? 0x9Fu : 0x8Fu) << 8 |
                           0x5Du << 16 | (down ? 127u << 24 : 0)));
        smc_poll();
    } else message(down ? 0x90 : 0x80, 0x5D, down ? 127 : 0);
}
static void hold_ms(unsigned ms) { now_ms += ms; smc_poll(); }
static void lost_release(int host, unsigned note)
{
    for (unsigned n = 0; n < SMC_Q; n++) {
        if (host) CHECK(smc_midi_host(11u | 0xBFu << 8 | 16u << 16));
        else { const uint8_t m[3] = {0xB0, 16, 0}; smc_ble_midi(m, 3); }
    }
    if (host) CHECK(smc_midi_host(8u | 0x8Fu << 8 | note << 16));
    else { const uint8_t m[3] = {0x80, (uint8_t)note, 0}; smc_ble_midi(m, 3); }
}
static void gesture(void)
{
    for (int host = 0; host < 2; host++) {
        setup(V_SEQ, PART_909); proj.set.bt |= PROJ_BT_SMC_USER;
        unsigned start = seq.req_start, stop = seq.req_stop;
        pause_edge(host, 1); CHECK(smc.locked);
        hold_ms(1500); CHECK(smc.locked); /* the capture press cannot unlock */
        pause_edge(host, 1); CHECK(smc.locked);
        pause_edge(host, 0);
        pause_edge(host, 1); CHECK(smc.locked); /* must not immediately toggle */
        hold_ms(899); CHECK(smc.locked);
        pause_edge(host, 0); hold_ms(1000); CHECK(smc.locked); /* cancellation */
        pause_edge(host, 1); hold_ms(450); pause_edge(host, 1);
        hold_ms(449); CHECK(smc.locked);
        hold_ms(1); CHECK(!smc.locked); /* no repeat event required at 900 ms */
        pause_edge(host, 1); hold_ms(1000); CHECK(!smc.locked);
        pause_edge(host, 0); pause_edge(host, 0); CHECK(!smc.locked);
        CHECK(seq.req_start == start && seq.req_stop == stop);
        pause_edge(host, 1); pause_edge(host, 0); CHECK(smc.locked);
        pause_edge(host, 1); now_ms += 900; pause_edge(host, 0);
        CHECK(!smc.locked && !smc.lock_down); /* deadline key-up, no intervening poll */

        pause_edge(host, 1); pause_edge(host, 0); CHECK(smc.locked);
        pause_edge(host, 1); hold_ms(899); lost_release(host, 0x5D);
        hold_ms(1); CHECK(smc.locked && !smc.lock_down); /* drain loss before timer */
        pause_edge(host, 1); hold_ms(450); lost_release(host, 8);
        hold_ms(450); CHECK(!smc.locked); /* unrelated key-up cannot cancel */
        pause_edge(host, 0);
        pause_edge(host, 1); pause_edge(host, 0);
        now_ms = UINT32_MAX - 449u; pause_edge(host, 1);
        hold_ms(899); CHECK(smc.locked); hold_ms(1); CHECK(!smc.locked);
    }
    for (int cancel = 0; cancel < 4; cancel++) {
        setup(V_HOME, PART_303A);
        pause_edge(0, 1); pause_edge(0, 0); pause_edge(0, 1); hold_ms(899);
        if (cancel == 0) { smc_ble_link(0); smc_ble_link(1); }
        if (cancel == 1) ui.overlay = O_ASK;
        if (cancel == 2) perf.test = 0;
        if (cancel == 3) { CHECK(ui_project_begin() == 0); }
        hold_ms(1); CHECK(smc.locked && !smc.lock_down);
        if (cancel == 1) ui.overlay = O_NONE;
        if (cancel == 2) perf.test = PT_IDLE;
        if (cancel == 3) ui_project_end(0);
        pause_edge(0, 0); hold_ms(1000); CHECK(smc.locked);
        pause_edge(0, 1); hold_ms(900); CHECK(!smc.locked);
        pause_edge(0, 0); pause_edge(0, 1); pause_edge(0, 0); pause_edge(0, 1);
        smc_project_reset(); hold_ms(1000); CHECK(!smc.locked && !smc.lock_down);
    }
    puts("PASS 900 ms gesture: BLE/host, same press, repeat, 899 ms cancel, threshold, wrap, loss, reconnect, guards, reset, no transport");
}
static void clock_off(void *ctx, int part) { (void)ctx; (void)part; }
static const seq_sink_t clock_sink = {.bass_off = clock_off};
static void advance_clock(unsigned samples)
{
    seq_advance(&seq, samples, &clock_sink);
    now_ms += samples * 1000u / FS;
}
static unsigned clock_tick_samples = 882;
static void tick(void)
{
    CHECK(seq_clk_take(&seq, 0xF8, 0)); CHECK(seq_midi_rt(&seq, 0xF8));
    advance_clock(clock_tick_samples); /* exact 62.5/125/250 BPM tick periods */
}
static void beat(void)
{
    for (unsigned speed = 0; speed < 3; speed++)
    for (int external_only = 0; external_only < 2; external_only++) {
        clock_tick_samples = 1764u >> speed;
        float bpm = 62.5f * (float)(1u << speed);
        setup(V_HOME, PART_303A); seq.bpm = 125;
        seq.clk_src = external_only ? SEQ_CLK_EXT : SEQ_CLK_AUTO;
        advance_clock(1);
        for (unsigned n = 1; n <= 145; n++) {
            tick(); CHECK(smc_led(0x5D) == (((n - 1u) % 24u) < 12u));
        }
        CHECK(!seq.playing); /* clock pickup works while stopped */
        CHECK(seq.ext_period && seq.ext_bpm > bpm - 0.1f && seq.ext_bpm < bpm + 0.1f);
        seq.playing = 1; CHECK(seq_midi_rt(&seq, 0xFC)); advance_clock(1); CHECK(!seq.playing);
        CHECK(smc_led(0x5D));
        for (unsigned n = 0; n < 96; n++) {
            advance_clock(clock_tick_samples);
            CHECK(smc_led(0x5D) == (((n + 1u) % 24u) < 12u));
        }
        CHECK(external_only ? seq.clk_lost : !seq.ext);
        CHECK(seq.bpm == (float)(int)(bpm + 0.5f)); /* loss retains measured tempo, not the 1024 ms wall blink */
        smc_ble_link(0); smc_poll(); advance_clock(clock_tick_samples * 24u); smc_ble_link(1); smc_poll();
        CHECK(smc_led(0x5D)); /* reconnect does not restart the visual phase */
        for (unsigned n = 1; n <= 48; n++) {
            tick(); CHECK(smc_led(0x5D) == (((n - 1u) % 24u) < 12u));
        }
        CHECK(smc_lock_toggle());
        for (unsigned n = 0; n < 48; n++) { tick(); CHECK(smc_led(0x5D)); }
        CHECK(smc_lock_toggle()); CHECK(!smc_led(0x5D)); /* current phase, not a new beat */
        smc_project_reset(); CHECK(!smc.locked); CHECK(smc_led(0x5D) == 0);
    }
    setup(V_HOME, PART_303A); seq.bpm = 125; seq.ext = 0;
    CHECK(smc_led(0x5D)); advance_clock(10584); CHECK(!smc_led(0x5D));
    advance_clock(10584); CHECK(smc_led(0x5D));
    seq.bpm = 250; CHECK(smc_led(0x5D)); advance_clock(5292); CHECK(!smc_led(0x5D));
    smc_project_reset(); seq.ext_now = UINT32_MAX - 5291u;
    CHECK(smc_led(0x5D)); seq.ext_now += 5292; CHECK(!smc_led(0x5D));
    seq.ext_now += 5292; CHECK(smc_led(0x5D));
    puts("PASS beat: 62.5/125/250 BPM pickup, AUTO/EXTERNAL last-BPM loss, STOP, reconnect, solid lock, unlock/reset, internal tempo, wrap");
}
int main(int argc, char **argv)
{
    if (argc < 2 || !strcmp(argv[1], "gesture")) gesture();
    if (argc < 2 || !strcmp(argv[1], "beat")) beat();
    printf("smc_lock_beat: PASS (%u production checks)\n", checks);
    return 0;
}

#!/usr/bin/env python3
"""Content identity for validation reuse, not permission to build or install.

Capture before and after validation. Hash dependency bytes (including dirty and
untracked reference files), resolved host tools, configuration and external runners.
No mtime cache: replacing bytes at the same path must invalidate evidence.
Install consumers check recorded provenance; they need not have the build SDK.
"""
import argparse
import csv
import hashlib
import importlib.metadata
import importlib.machinery
import json
import os
from pathlib import Path
import platform
import shutil
import stat
import subprocess
import sys

SCHEMA = 1
PINS = 'schwung-9W9=10cbe5c schwung-8W8=94aa271 schwung-303=7680578 schwung-tb3po=f49d81d'


def digest(data):
    return hashlib.sha256(data).hexdigest()


def encoded(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':')).encode()


def file_hash(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def content(path, ancestors=(), exclude=()):
    return _content_resolved(Path(path).resolve(strict=True), ancestors, exclude)


def _content_resolved(actual, ancestors, exclude):
    if actual in ancestors:
        raise ValueError('dependency symlink cycle: ' + str(actual))
    info = actual.stat()
    if stat.S_ISREG(info.st_mode):
        return {'sha256': file_hash(actual), 'executable': bool(info.st_mode & 0o111)}
    if not stat.S_ISDIR(info.st_mode):
        raise ValueError('not a dependency file/directory: ' + str(actual))
    # Git metadata is mutable bookkeeping, not a build input.
    with os.scandir(actual) as scan:
        entries = sorted(scan, key=lambda entry: entry.name)
    children = {}
    for entry in entries:
        if entry.name in ('.git', '__pycache__', *exclude):
            continue
        child = Path(entry.path)
        if entry.is_symlink():
            child = child.resolve(strict=True)
        children[entry.name] = _content_resolved(child, (*ancestors, actual), exclude)
    return {'sha256': digest(encoded(children))}


def git(repo, *args):
    return subprocess.check_output(['git', '-C', str(repo), *args], text=True).strip()


def source_tree(repo, commit):
    rows = git(repo, 'ls-tree', '-r', '--full-tree', commit).splitlines()
    return digest(''.join(r + '\n' for r in rows if not r.split('\t', 1)[-1].endswith('.md')).encode())


def _manifest_paths(dist):
    """Declared install paths, including ones no longer on disk.

    importlib.metadata.Distribution.files drops missing paths. A package that
    lost a declared file would then fingerprint as a smaller package.
    installed-files.txt is relative to the egg-info directory. A console script
    often lives in the env bin directory, outside site-packages. Keep that as an
    upward-relative path from the distribution root so locate_file can still
    open it. Do not require every declared file to reside below that root.
    """
    text = dist.read_text('RECORD')
    if text:
        return [row[0] for row in csv.reader(text.splitlines()) if row and row[0]]
    text = dist.read_text('installed-files.txt')
    subdir = getattr(dist, '_path', None)
    if text and subdir:
        root = Path(dist.locate_file('')).resolve()
        paths = []
        for name in text.splitlines():
            if name:
                located = (Path(subdir) / name).resolve()
                paths.append(located.relative_to(root, walk_up=True).as_posix())
        return paths
    text = dist.read_text('SOURCES.txt')
    if text:
        return [line for line in text.splitlines() if line]
    return None


def _module_roots(dist):
    """Top-level module names from top_level.txt, or from entry points when it is absent.

    A distro package can ship entry_points.txt and omit both RECORD and
    top_level.txt. An empty or unsafe top_level.txt is not replaced: that file
    was present and does not name modules.
    """
    text = dist.read_text('top_level.txt')
    if text is None:
        roots = []
        for point in dist.entry_points:
            if not point.pattern.match(point.value):
                continue
            module = point.module
            if module:
                roots.append(module.split('.', 1)[0])
        return roots
    return text.split()


def package_files(dist):
    """Hash a manifest, or declared installed modules when distro metadata omits it.

    Do not import modules: imports can execute code and select a shadowing copy.
    Missing/unsafe metadata must stop capture rather than authenticate no bytes.
    A declared manifest file that is not on disk raises OSError.
    """
    manifest = _manifest_paths(dist)
    if manifest is not None:
        files = {}
        for rel in manifest:
            if rel.endswith(('.pyc', '.pyo')):
                continue
            files[rel] = file_hash(dist.locate_file(rel))
    else:
        names = _module_roots(dist)
        if not names or any(not name.isidentifier() for name in names):
            raise ValueError('cannot enumerate Python package: missing or unsafe top_level.txt')
        root = Path(dist.locate_file('')).resolve(strict=True)
        files = {}

        def collect(path, ancestors=()):
            actual = path.resolve(strict=True)
            if root not in actual.parents or actual in ancestors:
                raise ValueError('unsafe Python package path: ' + str(path))
            if path.is_dir():
                for child in sorted(path.iterdir()):
                    if child.name != '__pycache__':
                        collect(child, (*ancestors, actual))
            elif path.is_file():
                if path.suffix not in ('.pyc', '.pyo'):
                    files[str(path.relative_to(root))] = file_hash(path)
            else:
                raise ValueError('not a Python package file/directory: ' + str(path))

        for name in sorted(set(names)):
            paths = [root / name] + [root / (name + suffix)
                                     for suffix in importlib.machinery.all_suffixes()
                                     if suffix not in ('.pyc', '.pyo')]
            installed = [p for p in paths if p.exists() or p.is_symlink()]
            if not installed:
                raise ValueError('cannot find installed Python module: ' + name)
            for path in installed:
                collect(path)
    if not files:
        raise ValueError('cannot fingerprint an empty installed Python package')
    return files


def runtime(config, env=None):
    """Hash the tools and Python packages in the command execution environment."""
    env = os.environ if env is None else env
    tools = {}
    dependencies = {}
    check_tools = []
    for check in config.get('plan', {}).get('checks', []):
        check_tools.append(check['argv'][0])
    for name in ('bash', 'sh', 'git', 'make', 'node', 'cc', 'c++', 'ld', 'ar', 'objcopy',
                 env.get('CC', 'cc'), env.get('CXX', 'c++'), sys.executable, *check_tools):
        resolved = shutil.which(name, path=env.get('PATH'))
        tools[name if name != sys.executable else 'python'] = content(resolved) if resolved else None
    # Include installed Python dependency contents, not merely version strings.
    packages = {}
    for name in sorted(set(['pillow', 'numpy'] + env.get('X0X_VALIDATION_PYTHON_PACKAGES', '').split())):
        try:
            dist = importlib.metadata.distribution(name)
        except importlib.metadata.PackageNotFoundError:
            packages[name] = None
            continue
        files = package_files(dist)
        packages[name] = {'version': dist.version, 'sha256': digest(encoded(files))}
    settings = {k: v for k, v in env.items() if k.startswith(('X0X_DEV_', 'FELUCCA_')) or k in (
        'CC', 'CXX', 'CFLAGS', 'CXXFLAGS', 'CPPFLAGS', 'LDFLAGS', 'CPATH', 'LIBRARY_PATH',
        'X0X_VERSION', 'X0X_BASS_PRESET_PREVIEW', 'X0X_BASS_TAGGED_SOUND',
        'X0X_BASS_NOTE_SOUND',
        'LD_LIBRARY_PATH', 'LD_PRELOAD', 'PYTHONPATH', 'NODE_PATH', 'NODE_OPTIONS',
        'X0X_CDC', 'X0X_DEBUG', 'X0X_BREAK_BANK', 'X0X_RAM_CANARY', 'X0X_SMK_LCD_BAUD',
        'X0X_FONTSET', 'X0X_FONT_DIRS', 'CTL_NATIVE', 'CTL_NO_CACHE', 'X0X_TEST_TIME_SCALE', 'BOARD', 'MODEL')}
    return {'tools': tools, 'python_packages': packages, 'environment': settings,
            'platform': [platform.system(), platform.machine(), platform.release()],
            'dependencies': dependencies}


def capture(repo, commit, mode, config, toolchain, sdk, refs=None, pins=PINS,
            env=None, runner_dir=None, hook=None, runner_path=None, execution=None):
    env = os.environ if env is None else env
    runner_dir = Path(runner_dir or Path(__file__).resolve().parent)
    runners = ['validation_inputs.py'] + (['gate.sh', 'gate_flashmap.py', 'gate_sigwrap.py']
                                         if mode == 'gate' else ['dev_validate.py'])
    dependencies = {'toolchain': content(toolchain), 'sdk': content(sdk)}
    references = {}
    if mode == 'gate':
        for pin in pins.split():
            name, want = pin.split('=', 1)
            path = Path(refs) / name
            head = git(path, 'rev-parse', 'HEAD')
            if not head.startswith(want):
                raise ValueError('reference pin mismatch: ' + name)
            references[name] = {'pin': want, 'commit': head, 'content': content(path)}
        dependencies['pre-push'] = content(hook or runner_dir / 'pre-push.hook')
    else:
        for key in ('NINEW9_DIR', 'EIGHTW8_DIR', 'SCHWUNG303', 'TB3PO_REF', 'X0X_REFS'):
            if env.get(key):
                references[key] = content(env[key])
    for path in config.get('dependencies', []):
        dependencies[path] = content(path)
    for check in config.get('plan', {}).get('checks', []):
        for arg in check['argv'][1:]:
            if Path(arg).is_absolute() and Path(arg).exists():
                dependencies[arg] = content(arg)
    execution = runtime(config, env) if execution is None else execution
    dependencies.update(execution['dependencies'])
    payload = {'schema': SCHEMA, 'mode': mode, 'source': source_tree(repo, commit),
               'configuration': config, 'environment': execution['environment'],
               'platform': execution['platform'],
               'validator': {name: content(runner_path if name == 'gate.sh' and runner_path else runner_dir / name) for name in runners},
               'tools': execution['tools'], 'python_packages': execution['python_packages'],
               'dependencies': dependencies, 'references': references}
    return {'schema': SCHEMA, 'sha256': digest(encoded(payload)), 'inputs': payload}


def validate(record, expected=None):
    if (not isinstance(record, dict) or record.get('schema') != SCHEMA or
            not isinstance(record.get('inputs'), dict) or
            record['inputs'].get('schema') != SCHEMA or
            record.get('sha256') != digest(encoded(record['inputs']))):
        raise ValueError('missing or invalid validation-input identity')
    if expected is not None and record['sha256'] != expected['sha256']:
        raise ValueError('validation inputs changed')
    return record['sha256']


def main():
    p = argparse.ArgumentParser(description=__doc__)
    sub = p.add_subparsers(dest='action', required=True)
    cap = sub.add_parser('capture')
    for name in ('repo', 'commit', 'toolchain', 'sdk', 'refs', 'hook'):
        cap.add_argument('--' + name, required=True)
    cap.add_argument('--pins', default=PINS)
    cap.add_argument('--runner')
    verify = sub.add_parser('verify')
    verify.add_argument('file')
    verify.add_argument('--sha256', required=True)
    verify.add_argument('--source', required=True)
    a = p.parse_args()
    try:
        if a.action == 'capture':
            print(json.dumps(capture(a.repo, a.commit, 'gate',
                {'models': ['elite', 'pro'], 'configs': {'dev': 1, 'rel': 0}, 'time_scale': 1},
                a.toolchain, a.sdk, a.refs, a.pins, hook=a.hook, runner_path=a.runner), sort_keys=True))
        else:
            record = json.loads(Path(a.file).read_text())
            if (validate(record) != a.sha256 or record['inputs'].get('source') != a.source or
                    record['inputs'].get('mode') != 'gate'):
                raise ValueError('validation-input provenance mismatch')
    except (OSError, ValueError, subprocess.SubprocessError) as e:
        print('validation inputs: ' + str(e), file=sys.stderr)
        return 2
    return 0


if __name__ == '__main__':
    sys.exit(main())

/* SPDX-License-Identifier: GPL-3.0-only */
/* Chicago amp Env Attack/Decay/Sustain/Release on native303. Defaults preserve Open303
 * Env decay-while-held; Gate mode still holds VCA; AmpMod index 16 untouched. */
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "bass303.h"

static int fails;
#define CHECK(c, ...) do { if (!(c)) { printf("FAIL " __VA_ARGS__); printf("\n"); fails++; } } while (0)

static float buf[44100];

static double rms_range(const float *x, int a, int b)
{
    double s = 0;
    int i, n = b - a;
    if (n <= 0)
        return 0;
    for (i = a; i < b; i++)
        s += (double)x[i] * (double)x[i];
    return sqrt(s / (double)n);
}

static void test_surface(void)
{
    const x0x_param_t *a = bass303_param(BASS303_AATTACK);
    const x0x_param_t *d = bass303_param(BASS303_ADECAY);
    const x0x_param_t *s = bass303_param(BASS303_ASUSTAIN);
    const x0x_param_t *r = bass303_param(BASS303_ARELEASE);
    CHECK(BASS303_AMPMODE == 16, "AmpMod stays at 16");
    CHECK(BASS303_GNAW == 17, "Gnaw stays at 17");
    CHECK(BASS303_BITE == 18, "Bite index is 18");
    CHECK(BASS303_AATTACK == 19 && BASS303_ADECAY == 20 && BASS303_ASUSTAIN == 21 &&
          BASS303_ARELEASE == 22, "amp ADSR indices 19..22");
    CHECK(bass303_nparams() == 23, "nparams includes Bite + amp ADSR");
    CHECK(a && a->def == 0 && !strcmp(a->name, "AAtt"), "AAtt default 0");
    CHECK(d && d->def == 64 && !strcmp(d->name, "ADec"), "ADec default 64 (~1230 ms)");
    CHECK(s && s->def == 0 && !strcmp(s->name, "ASus"), "ASus default 0");
    CHECK(r && r->def == 0 && !strcmp(r->name, "ARel"), "ARel default 0 (stock release)");
}

static void test_default_env_still_decays(void)
{
    bass303_t b;
    double e0, e1;
    int pos = 0;
    bass303_init(&b);
    CHECK(bass303_get(&b, BASS303_AATTACK) == 0, "init AAtt 0");
    CHECK(bass303_get(&b, BASS303_ADECAY) == 64, "init ADec 64");
    CHECK(bass303_get(&b, BASS303_ASUSTAIN) == 0, "init ASus 0");
    CHECK(bass303_get(&b, BASS303_AMPMODE) == BASS303_AMP_ENV, "init AmpMod Env");
    bass303_set(&b, BASS303_VOLUME, 96);
    bass303_set(&b, BASS303_DRIVE, 0);
    bass303_set(&b, BASS303_ENVMOD, 0);
    bass303_note_on_velocity(&b, 48, 0, 0, 100);
    while (pos < 44100) {
        int m = 128;
        if (pos + m > 44100)
            m = 44100 - pos;
        bass303_render(&b, buf + pos, m);
        pos += m;
    }
    e0 = rms_range(buf, 2205, 4410);
    e1 = rms_range(buf, 17640, 19845);
    CHECK(b.amp_y < 0.85f, "default Env amp_y decays (got %g)", (double)b.amp_y);
    CHECK(e0 > 1e-6 && e1 > 1e-6, "default Env produces audio");
    CHECK(20.0 * log10(e1 / e0) < -0.5, "default Env output falls while held");
}

static void test_sustain_holds(void)
{
    bass303_t b;
    int pos = 0;
    bass303_init(&b);
    bass303_set(&b, BASS303_AMPMODE, BASS303_AMP_ENV);
    bass303_set(&b, BASS303_AATTACK, 0);
    bass303_set(&b, BASS303_ADECAY, 5);   /* ~96 ms → settle well within 2 s */
    bass303_set(&b, BASS303_ASUSTAIN, 64);
    bass303_set(&b, BASS303_VOLUME, 96);
    bass303_set(&b, BASS303_DRIVE, 0);
    bass303_set(&b, BASS303_ENVMOD, 0);
    bass303_note_on_velocity(&b, 48, 0, 0, 100);
    while (pos < 88200) {
        float tmp[128];
        int m = 128;
        if (pos + m > 88200)
            m = 88200 - pos;
        bass303_render(&b, tmp, m);
        pos += m;
    }
    CHECK(b.amp_stage == BASS303_AMP_SUS || fabsf(b.amp_y - b.asustain) < 0.02f,
          "reached sustain (stage=%d amp_y=%g sus=%g)", b.amp_stage,
          (double)b.amp_y, (double)b.asustain);
    CHECK(fabsf(b.amp_y - b.asustain) < 0.02f, "amp_y near sustain (got %g want %g)",
          (double)b.amp_y, (double)b.asustain);
}

static void test_attack_delays_peak(void)
{
    bass303_t fast, slow;
    double rf, rs;
    int pos;
    bass303_init(&fast);
    bass303_set(&fast, BASS303_AATTACK, 0);
    bass303_set(&fast, BASS303_ASUSTAIN, 127);
    bass303_set(&fast, BASS303_ADECAY, 10);
    bass303_set(&fast, BASS303_VOLUME, 96);
    bass303_set(&fast, BASS303_DRIVE, 0);
    bass303_set(&fast, BASS303_ENVMOD, 0);
    bass303_note_on_velocity(&fast, 48, 0, 0, 100);
    for (pos = 0; pos < 2048; ) {
        int m = 128;
        bass303_render(&fast, buf + pos, m);
        pos += m;
    }
    rf = rms_range(buf, 0, 512);

    bass303_init(&slow);
    bass303_set(&slow, BASS303_AATTACK, 100);
    bass303_set(&slow, BASS303_ASUSTAIN, 127);
    bass303_set(&slow, BASS303_ADECAY, 10);
    bass303_set(&slow, BASS303_VOLUME, 96);
    bass303_set(&slow, BASS303_DRIVE, 0);
    bass303_set(&slow, BASS303_ENVMOD, 0);
    bass303_note_on_velocity(&slow, 48, 0, 0, 100);
    for (pos = 0; pos < 2048; ) {
        int m = 128;
        bass303_render(&slow, buf + pos, m);
        pos += m;
    }
    rs = rms_range(buf, 0, 512);
    CHECK(rf > 1e-5, "instant attack has early energy");
    CHECK(rs < rf * 0.85, "slow attack quieter in first 512 samples (slow %g fast %g)", rs, rf);
}

static void test_gate_unchanged(void)
{
    bass303_t b;
    int pos = 0;
    bass303_init(&b);
    bass303_set(&b, BASS303_AMPMODE, BASS303_AMP_GATE);
    bass303_set(&b, BASS303_AATTACK, 80);
    bass303_set(&b, BASS303_ASUSTAIN, 40);
    bass303_set(&b, BASS303_VOLUME, 96);
    bass303_set(&b, BASS303_DRIVE, 0);
    bass303_note_on_velocity(&b, 48, 0, 0, 100);
    while (pos < 22050) {
        int m = 128;
        bass303_render(&b, buf + pos, m);
        pos += m;
    }
    CHECK(fabsf(b.amp_y - 1.0f) < 1e-6f, "Gate still holds at 1 despite amp ADSR pots");
}

static void test_bite_changes_output(void)
{
    bass303_t clean, bitten;
    double rc, rb;
    int pos;
    bass303_init(&clean);
    bass303_set(&clean, BASS303_CUTOFF, 100);
    bass303_set(&clean, BASS303_RESO, 40);
    bass303_set(&clean, BASS303_GNAW, 0);
    bass303_set(&clean, BASS303_BITE, 0);
    bass303_set(&clean, BASS303_DRIVE, 0);
    bass303_set(&clean, BASS303_AMPMODE, BASS303_AMP_GATE);
    bass303_set(&clean, BASS303_VOLUME, 96);
    bass303_note_on_velocity(&clean, 36, 0, 0, 100);
    for (pos = 0; pos < 4096; ) {
        int m = 4096 - pos > 128 ? 128 : 4096 - pos;
        bass303_render(&clean, buf + pos, m);
        pos += m;
    }
    rc = rms_range(buf, 512, 3584);

    bass303_init(&bitten);
    bass303_set(&bitten, BASS303_CUTOFF, 100);
    bass303_set(&bitten, BASS303_RESO, 40);
    bass303_set(&bitten, BASS303_GNAW, 0);
    bass303_set(&bitten, BASS303_BITE, 100);
    bass303_set(&bitten, BASS303_DRIVE, 0);
    bass303_set(&bitten, BASS303_AMPMODE, BASS303_AMP_GATE);
    bass303_set(&bitten, BASS303_VOLUME, 96);
    bass303_note_on_velocity(&bitten, 36, 0, 0, 100);
    for (pos = 0; pos < 4096; ) {
        int m = 4096 - pos > 128 ? 128 : 4096 - pos;
        bass303_render(&bitten, buf + pos, m);
        pos += m;
    }
    rb = rms_range(buf, 512, 3584);
    CHECK(bass303_param(BASS303_BITE) && bass303_param(BASS303_BITE)->def == 0, "Bite default 0");
    CHECK(fabsf(bitten.bite - (100.0f / 127.0f)) < 1e-5f, "Bite 100 stores fraction");
    CHECK(rc > 1e-5 && rb > 1e-5, "clean and Bite produce audio");
    CHECK(fabs(rb - rc) / rc > 0.01, "Bite changes output vs clean (clean %g bite %g)", rc, rb);
}

int main(void)
{
    test_surface();
    test_default_env_still_decays();
    test_sustain_holds();
    test_attack_delays_peak();
